/* ===== yl-R023 medlog: \u6bcf\u6b21\u505c\u6b62\u6253\u5750\u5199\u4e00\u6761\u300c\u672c\u6b21\u6253\u5750\u6536\u76ca\u300d\u65e5\u5fd7 =====
   \u5728 Hw \u7684\u6253\u5750 interval effect \u65c1\u6302\u4e00\u4e2a\u4f9d\u8d56 [autoMeditate] \u7684\u65c1\u8def effect\uff1a
   autoMeditate \u7531 false->true \u8bb0\u4f1a\u8bdd\u8d77\u70b9\u5e76\u6e05\u7d2f\u52a0\u5668\uff0ctrue->false \u7ed3\u7b97\u5e76\u5199\u65e5\u5fd7\u3002
   \u8986\u76d6\u5168\u90e8\u505c\u6b62\u8def\u5f84\uff08\u624b\u52a8\u6309\u94ae / \u6218\u6597 / \u6b7b\u4ea1 / \u5546\u5e97 / \u58f0\u671b\u4e8b\u4ef6\u7b49\u81ea\u52a8\u6682\u505c\uff09\uff0c
   \u4e0d\u9010\u4e2a\u6539\u5f00\u5173\u3002
   \u2605 \u6570\u503c\u53e3\u5f84\uff08\u7b56\u5212 \u00a73.2\uff09\uff1a\u4fee\u4e3a/\u7075\u77f3/\u8df3\u6570/\u987f\u609f\u6b21\u6570\u4e00\u5f8b\u53d6\u81ea handleMeditate \u5185
     \u5c31\u5730\u7d2f\u52a0\u7684\u6bcf\u8df3 S \u4e0e\u6bcf\u8df3\u7075\u77f3\uff0c\u65e5\u5fd7\u5c42\u53ea\u505a\u8bfb\u53d6\u4e0e\u683c\u5f0f\u5316\uff0c\u4e0d\u53e6\u7b97\u4efb\u4f55\u516c\u5f0f\u3002
     \u987f\u609f\u8ba1\u6570\u76f4\u63a5\u590d\u7528\u672c\u4f53\u5e03\u5c14 b\uff08\u540c\u6e90\u5224\u5b9a\uff0cR-022 \u6539\u9608\u503c\u540e\u96f6\u6539\u52a8\u8ddf\u968f\uff09\u3002 */
function YlxwMedDur(ms) {
  var s = Math.max(0, Math.floor(Number(ms) || 0) / 1000);
  var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = Math.floor(s % 60);
  if (h > 0) return h + " \u5c0f\u65f6 " + m + " \u5206";
  if (m > 0) return m + " \u5206 " + ss + " \u79d2";
  return ss + " \u79d2";
}
var YLXW_MED_SESS = null;
var YLXW_MED_ACC = { exp: 0, stone: 0, ticks: 0, insight: 0 };
/* \u6bcf\u8df3\u7d2f\u52a0\uff08handleMeditate \u5185\u5c31\u5730\u8c03\u7528\uff09\u3002\u4f1a\u8bdd\u672a\u5f00\u59cb\u5219\u4e22\u5f03\uff0c\u9632\u624b\u52a8\u5355\u70b9\u6c61\u67d3\u65e5\u5fd7\u3002 */
/* ===== yl-R165 wudao-enlighten: meditate insight also yields WUDAO insight =====
   Same trigger point as the meditate "insight" (bundle: Math.random()<.004).
   Fire-and-forget POST /wudao/enlighten -> server picks one of the player's
   UNLOCKED dao, credits +WUDAO_INSIGHT_EXP via wudaoAddExp(...,'idle'), and
   self-throttles. Any failure/throttle is swallowed: the meditate loop is never
   affected. On success only, append one log line after the insight line.
   MUST use the project request wrapper YlxwPost (no raw fetch). */
function YlxwWudaoEnlighten(addLog) {
  try {
    YlxwPost("/wudao/enlighten", {}).then(function (r) {
      if (r && r.ok && r.daoName) {
        try { addLog("\u262f\u0020\u609f\u9053\u3010" + r.daoName + "\u3011\u5fc3\u5f97\u0020\u002b" + (r.expGain || 0), "special"); } catch (e) {}
      }
    }).catch(function () {});
  } catch (e) {}
}
/*[r184wudao]*/
/* ===== yl-R184 wudao-on-rare-adventure =====
   The 悟道 panel hint promises "打坐 / 历练中会随机触发悟道经验提升", but
   YlxwWudaoEnlighten() was wired ONLY to the meditate insight point (R-165/R-188);
   the adventure path never called it => 悟道 never fired during auto-adventure.
   This wires it into the auto-adventure TEMPLATE-EVENT path (executeAdventure),
   firing ONLY on the rare high-value events the player calls "加几千灵石":
   advType normal/lucky AND template base spirit stones >= YLXW_WUDAO_ADV_STONE_MIN.
   JUDGE = template RAW stones (not settled): raw>=200 <=> the 奇遇(lucky) event
   (lucky raw 202..497 after R-180 v2), which settles to ~1030..2535 stones at
   QiRefining (settle = raw * u * 5.1, u>=1). Realm-stable rate ~5%..19%/run.
   INTEGRATION ORDER: requires R-180 v2 (E3 rollback, lucky 20-70 -> 200-500) to be
   applied FIRST; otherwise lucky raw stays 20-69 and this never fires.
   Fire-and-forget + server-side self-throttle; any failure is swallowed and never
   affects the adventure loop. MUST reuse YlxwWudaoEnlighten (no raw fetch). */
var YLXW_WUDAO_ADV_STONE_MIN = 200;
function YlxwWudaoMaybe(tpl, advType, addLog) {
  try {
    if (!tpl) return;
    if (advType !== "normal" && advType !== "lucky") return;
    if ((Number(tpl.spiritStonesChange) || 0) < YLXW_WUDAO_ADV_STONE_MIN) return;
    YlxwWudaoEnlighten(addLog);
  } catch (e) {}
}
function YlxwMedTick(S, insight) {
  if (!YLXW_MED_SESS) return;
  YLXW_MED_ACC.exp += Number(S) || 0;
  YLXW_MED_ACC.ticks += 1;
  if (insight) YLXW_MED_ACC.insight += 1;
}
/* \u6bcf\u8df3\u7075\u77f3\uff1a\u8fd4\u56de\u503c\u9010\u5b57\u4e0d\u53d8\uff08\u8868\u8fbe\u5f0f\u7ea7\u65e0\u526f\u4f5c\u7528\uff09\uff0c\u987a\u5e26\u7d2f\u52a0\u3002 */
function YlxwMedStone(v) {
  if (YLXW_MED_SESS) YLXW_MED_ACC.stone += Number(v) || 0;
  return v;
}
function YlxwMedSession(on) {
  try {
    var p = Be.getState().player;
    if (on) {
      if (!p) return;
      YLXW_MED_SESS = { t: Date.now() };
      YLXW_MED_ACC = { exp: 0, stone: 0, ticks: 0, insight: 0 };
      return;
    }
    var st = YLXW_MED_SESS; YLXW_MED_SESS = null;
    if (!st) return;
    var ms = Math.max(0, Date.now() - st.t);
    if (ms < 3000) return;
    var a = YLXW_MED_ACC, tk = a.ticks;
    var de = Math.floor(a.exp), ds = Math.floor(a.stone);
    var ae = tk > 0 ? Math.floor(de / tk) : 0;
    var as = tk > 0 ? Math.floor(ds / tk) : 0;
    Be.getState().addLog("\ud83e\uddd8 \u672c\u6b21\u6253\u5750 " + YlxwMedDur(ms)
      + "\uff1a\u4fee\u4e3a +" + de.toLocaleString()
      + " \u00b7 \u7075\u77f3 +" + ds.toLocaleString()
      + " \u00b7 \u5171\u6253\u5750 " + tk + " \u6b21"
      + " \u00b7 \u987f\u609f " + a.insight + " \u6b21"
      + " \u00b7 \u5e73\u5747\u6bcf\u8df3 \u4fee\u4e3a +" + ae.toLocaleString()
      + " / \u7075\u77f3 +" + as.toLocaleString(), "gain");
  } catch (e) {}
}


/* ===== yl-R105 advend105: one summary log when the user STOPS auto-adventure =====
   Mirrors yl-R023 medlog (which hooks autoMeditate). Here we hook the autoAdventure
   prop of component Hw via a side effect with dependency [r] (r = autoAdventure).
   A session starts on false->true and ends only on a real user stop. Every temporary
   auto-pause (battle / shop / reputation event / heaven-earth-soul / tribulation)
   commits its pausedBy* flag in the SAME React commit that sets autoAdventure=false,
   so on the off-edge we read Ze.getState(): if ANY pausedBy* is true we KEEP the
   session (temporary pause, no log); only when all pausedBy* are false is it a real
   user stop => emit exactly one summary line. Accumulation reuses R-089's settlement
   point (right after the YlxwAdvResultLog call) so the numbers are the amounts
   actually credited. No player field is added (no save-schema change). */
