/* ===== yl-0.8.5: secret-realm daily cap wired to the server ledger =====
   Server owns the authoritative "entered today" counter:
     GET  /dungeon/status  -> { date, count, cap, remaining, cdLeftMs, canEnter }
     POST /dungeon/entry   -> 200 { ok, count, cap, remaining, cdMs }
                              403 { ok:false, reason:'cap'|'cd', error, retryAfterMs }

   NOTE: we must NOT reuse Xc()/YlxwPost() for the entry call. Xc() treats HTTP 403
   as an unrecoverable session error and force-logs-out the player, while
   /dungeon/entry answers 403 for BOTH "daily cap reached" and "too frequent".
   So we post with the same primitive the trade market uses (jo() header + Nd()
   query) and read the status code ourselves.

   Policy: 403 -> deny (show the server's own message). Anything else -> fail OPEN,
   because the server ledger is a soft gate and a server hiccup must not lock
   players out of the content. The server still keeps its own ledger regardless. */
var YLXW_DG_ENTRY = "/dungeon/entry";
var YLXW_DG_STATUS = "/dungeon/status";

function YlxwDungeonToday() {
  try {
    var W = new Date();
    return W.getFullYear() + "-" + (W.getMonth() + 1) + "-" + W.getDate();
  } catch (e) { return ""; }
}
/* Mirror the server count into window.__ylDg so the pre-existing local gate and
   its "\u4eca\u65e5\u5df2\u63a2\u7d22 x/3" displays (ylDgGate, unchanged) reflect server truth. */
function YlxwDungeonMarkLocal(count) {
  try {
    var n = Number(count);
    if (!isFinite(n) || n < 0) return;
    if (YLXW_DG_ENTRY_MODE) { window.__ylDg = { d: YlxwDungeonToday(), cnt: Math.floor(n), cd: YlxwDgCdUntil() }; } else { YLXW_DG_NORM_CNT = Math.floor(n); }
  } catch (e) {}
}

/* ===== yl-R032: \u79d8\u5883\u300c\u51b7\u5374\u5236\u5ea6\u300d+\u300c\u6bcf\u65e5\u4e0a\u9650\u968f\u7b49\u9636 10\u219220\u300d=====
   \u2460 \u51b7\u5374\uff1a\u8fdb\u5165\u6210\u529f\u5373\u5199 window.__ylDg.cd = now + 5 \u5206\u949f\uff08\u7b56\u5212 D12-A\uff0c\u4e0e
      \u670d\u52a1\u7aef DUNGEON_ENTRY_CD_MS=300000 \u540c\u6e90\uff09\uff0c\u5e76\u628a\u300c\u670d\u52a1\u7aef cdLeftMs\u300d\u4e0e
      \u300c\u672c\u5730\u5269\u4f59\u300d\u53d6\u8f83\u665a\u8005\uff0c\u907f\u514d\u5f00\u9762\u677f\u88ab StatusSync \u6e05\u96f6\u3002
   \u2461 \u4e0a\u9650\uff1aYLXW_DG_CAP = \u70bc\u6c14 10 \u2192 \u957f\u751f 20\uff087 \u6863\uff0c\u7528\u6237\u6700\u65b0\u62cd\u677f\uff09\uff0c\u4e0e\u670d\u52a1\u7aef\u540c\u4e00\u5f20\u8868\u3002
      \u2605 \u4e0d\u6539 ylDgGate() \u672c\u4f53\uff08dungeon085 \u95e8\u7981\u51bb\u7ed3\uff09\uff0ccap \u5728\u8c03\u7528\u70b9\u7528 YlxwDgCap \u6c42\u503c\u3002 */
var YLXW_DG_CD_MS = 15 * 60 * 1000;
var YLXW_DG_CAP = [10, 12, 14, 15, 17, 18, 20];
var YLXW_DG_SRV_CD = 0;
function YlxwDgCap(realm) {
  try {
    var i = fe.indexOf(realm);
    if (!(i >= 0)) i = 0;
    if (i > YLXW_DG_ROGUE_CAP.length - 1) i = YLXW_DG_ROGUE_CAP.length - 1;
    return YLXW_DG_ROGUE_CAP[i];
  } catch (e) { return YLXW_DG_ROGUE_CAP[0]; }
}
/* \u51b7\u5374\u5269\u4f59 = max(\u672c\u5730\u5269\u4f59, \u670d\u52a1\u7aef cdLeftMs)\uff0c\u4e24\u8005\u53d6\u8f83\u665a\u8005\uff08\u670d\u52a1\u7aef\u672a\u4e0a\u7ebf\u65f6\u672c\u5730\u4ecd\u751f\u6548\uff09\u3002
   \u670d\u52a1\u7aef\u51b7\u5374\u7ecf\u6a21\u5757\u7ea7 YLXW_DG_SRV_CD \u4f20\u5165 \u2014\u2014 \u4e0d\u6539 YlxwDungeonMarkLocal(count) \u7b7e\u540d\u3002 */
function YlxwDgCdUntil() {
  var prev = 0;
  try { prev = Number(window.__ylDg && window.__ylDg.cd) || 0; } catch (e0) { prev = 0; }
  var srv = Number(YLXW_DG_SRV_ROGUE_CD) > 0 ? Date.now() + Number(YLXW_DG_SRV_ROGUE_CD) : 0;
  return Math.max(prev, srv);
}


/* ===== yl-R063: roguelike dungeon gets its own daily ledger + cap table =====
   User R-063: count the roguelike mode separately; the old [10..20] table
   stays with the popup realm; roguelike starts at 3/day for the lowest realm.
   Split summary:
     - server (srv_patch_063.py) tracks rogue_count/rogue_last_ts separately
       and reports rogueCount/rogueCap/rogueCdLeftMs on /dungeon/status;
     - entry posts carry mode:"rogue"|"normal" (mode set right before each
       await-gate call site, synchronous segment, no interleave possible);
     - count mirroring is mode-aware: rogue -> window.__ylDg (rogue panel),
       popup -> YLXW_DG_NORM_CNT (popup panel reads server status directly);
     - rogue cap by realm lives in YLXW_DG_ROGUE_CAP, consumed inside the
       YlxwDgCap() body (its 6 call sites and the old [10..20] var stay put). */
var YLXW_DG_ENTRY_MODE = 0;   /* 0 = popup realm entry, 1 = roguelike dungeon entry */
var YLXW_DG_NORM_CNT = 0;     /* popup realm daily count mirror (display comes from server status) */
var YLXW_DG_SRV_ROGUE_CD = 0; /* roguelike cooldown left (ms), from server status rogueCdLeftMs */
var YLXW_DG_ROGUE_CAP = [3, 5, 7, 8, 10, 11, 13]; /* rogue daily cap by realm: QiRefining 3 -> Longevity 13 */

async function YlxwDungeonStatusSync() {
  try {
    var tk = null;
    try { tk = Et.getState().token; } catch (e0) { tk = null; }
    if (!tk) return null;
    var s = await YlxwGet(YLXW_DG_STATUS);
    if (s && typeof s.count === "number") { YLXW_DG_ENTRY_MODE = 0; YLXW_DG_SRV_CD = Number(s.cdLeftMs) || 0; YlxwDungeonMarkLocal(s.count); }
    if (s && typeof s.rogueCount === "number") { YLXW_DG_SRV_ROGUE_CD = Number(s.rogueCdLeftMs) || 0; YLXW_DG_ENTRY_MODE = 1; YlxwDungeonMarkLocal(s.rogueCount); YLXW_DG_ENTRY_MODE = 0; }
    return s || null;
  } catch (e) { return null; }
}
async function YlxwDungeonEntryPost() {
  return await fetch(Nd(ln + YLXW_DG_ENTRY), {
    method: "POST",
    headers: Object.assign({ "Content-Type": "application/json" }, jo()),
    body: JSON.stringify({ mode: YLXW_DG_ENTRY_MODE ? "rogue" : "normal" })
  });
}
/* -> { ok:true, count?, remaining?, degraded? } | { ok:false, msg } ; never throws */
async function YlxwDungeonEntryGate() {
  try {
    var tk = null;
    try { tk = Et.getState().token; } catch (e0) { tk = null; }
    if (!tk) return { ok: true, degraded: "no-token" };
    var res = await YlxwDungeonEntryPost();
    if (res && res.status === 401) {
      try { await pS(); res = await YlxwDungeonEntryPost(); } catch (eR) {}
    }
    var data = null;
    try { data = await res.json(); } catch (e1) { data = null; }
    try { if (typeof YLApplyBalance === "function") YLApplyBalance(data); } catch (e2) {}
    if (res.status === 403) {
      return { ok: false, msg: (data && data.error) || "\u4eca\u65e5\u79d8\u5883\u6b21\u6570\u5df2\u7528\u5b8c\uff0c\u660e\u65e5\u518d\u6765\u3002" };
    }
    if (!res.ok) return { ok: true, degraded: "status-" + res.status };
    if (data && typeof data.count === "number") YlxwDungeonMarkLocal(data.count);
    return { ok: true, count: data && data.count, remaining: data && data.remaining };
  } catch (e) {
    return { ok: true, degraded: "network" };
  }
}

function YlxwMin(r) { return r >= 6e4 ? Math.ceil(r / 6e4) + " \u5206\u949f" : Math.ceil(r / 1e3) + " \u79d2"; }

/* ===== yl-0.8.3/0.8.4: Character-Dex spirit-stone gift dynamic pricing (cli-char) =====
   R = clamp( round(1000 * 2^(F/40)), 1000, 16000 ),  F = favorability
   F<=0 -> 1000 ; F=40 -> 2000 ; F=80 -> 4000 ; F=120 -> 8000 ; F>=160 -> 16000
   Base was 25 in 0.8.3; slowed to 40 in 0.8.4 (0->100 total 100876 -> 51452).
   Fully guarded: never returns NaN / undefined / negative (NaN would corrupt the save). */
function YlxwGiftCost(fav) {
  try {
    var F = YlxwNum(fav);
    if (!isFinite(F)) return F > 0 ? 16000 : 1000;
    var R = Math.round(1000 * Math.pow(2, F / 40));
    if (!isFinite(R)) return F > 0 ? 16000 : 1000;
    return Math.max(1000, Math.min(16000, R));
  } catch (e) { return 1000; }
}

function YlxwNum(r) { return Number(r) || 0; }
