var YlxwArenaPtLose = [5, 5, 5, 6, 6, 7, 7];          /* \u8d1f\uff08\u6263\u5206\uff0c\u4e0b\u9650 0\uff09 */

/* --- \u8bd5\u70bc\u5e38\u6570\uff08T16 \u00a75.1/\u00a75.2/\u00a75.3\uff09 --- */
