var YlxwSP_PREFIX = ["\u4e5d\u5929", "\u592a\u865a", "\u4e07\u8c61", "\u6df7\u6c8c", "\u7384\u5929", "\u8bdb\u4ed9", "\u9020\u5316", "\u7d2b\u9704", "\u7eaf\u9633", "\u592a\u9634", "\u516b\u8352", "\u4e7e\u5764", "\u5e7d\u51a5", "\u5bc2\u706d", "\u7f57\u777a", "\u5929\u7f61", "\u5730\u715e", "\u5927\u884d", "\u65e0\u6781", "\u9e3f\u8499"];
