/* \u7279\u6b8a\u5c5e\u6027\u8349\u79cd\u690d\u6240\u9700\u5883\u754c = \u5143\u5a74\u671f\uff08fe \u7b2c 4 \u6863 / index 3\uff09 */
var YLXW_FT_RARE_REALM = 3;
/* \u4e09\u6863\u663e\u793a\u540d */
var YLXW_FT_GRADE_CN = { normal: "\u666e\u901a", attr: "\u57fa\u7840\u5c5e\u6027", rare: "\u7279\u6b8a\u5c5e\u6027" };

/* \u73a9\u5bb6\u5883\u754c\u5e8f\uff08\u4f18\u5148\u6e38\u620f\u6743\u5a01 fe\uff1b\u53d6\u4e0d\u5230\u9000\u56de\u672c\u5730\u8868\uff0c\u7f3a\u7701 0 = \u6700\u4f4e\uff09 */
